<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';$me=require_login();$doctorId=(int)($_GET['doctor']??$_POST['doctor_id']??0);$d=do580_doctor($doctorId);if(!$d||$d['approval_status']!=='approved'){http_response_code(404);exit('Doctor not found.');}$mode=in_array((string)($_GET['mode']??$_POST['consultation_mode']??'video'),['video','audio','chat','in_person'],true)?(string)($_GET['mode']??$_POST['consultation_mode']??'video'):'video';$slots=do580_slots($doctorId,14,$mode);$sub=do580_patient_plan_active((int)$me['id']);$family=[];try{$q=db()->prepare('SELECT * FROM health_family_members_v580 WHERE tenant_id=? AND owner_user_id=? ORDER BY name');$q->execute([do580_tid(),(int)$me['id']]);$family=$q->fetchAll()?:[];}catch(Throwable $e){}$flash='';$error='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$id=do580_create_appointment((int)$me['id'],$_POST);header('Location: /my-health.php?booked='.$id);exit;}catch(Throwable $e){$error=$e->getMessage();}$slots=do580_slots($doctorId,14,$mode);}do580_public_header('Book '.$d['display_name'],'Book an online or in-person doctor appointment.');
