<section class="do580-pagehead"><div class="do580-shell"><h1>Book appointment</h1><p>Choose consultation mode, available time and payment option.</p></div></section><main class="do580-shell"><div class="do580-main-grid" style="margin:28px 0"><section class="do580-panel"><div style="display:flex;gap:15px;align-items:center"><div class="do580-avatar"><?php if($d['photo_url']):?><img src="<?=e($d['photo_url'])?>" alt=""><?php else:?><?=e(mb_strtoupper(mb_substr($d['display_name'],0,1)))?><?php endif;?></div><div><h2 style="margin:0"><?=e($d['display_name'])?></h2><p><?=e($d['specialty_name']?:'Medical Doctor')?> · <?=e($d['organization_name']?:'Online practice')?></p></div></div><?php if($error):?><div class="do580-alert err"><?=e($error)?></div><?php endif;?><form class="do580-form" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><label>Consultation mode<select name="consultation_mode" onchange="location='?doctor=<?=$doctorId?>&mode='+this.value"><option value="video" <?=$mode==='video'?'selected':''?>>Video consultation</option><option value="audio" <?=$mode==='audio'?'selected':''?>>Audio consultation</option><option value="chat" <?=$mode==='chat'?'selected':''?>>Chat consultation</option><option value="in_person" <?=$mode==='in_person'?'selected':''?>>In-person visit</option></select></label><label>Patient<select name="family_member_id"><option value="">Myself — <?=e($me['name'])?></option><?php foreach($family as $f):?><option value="<?=(int)$f['id']?>"><?=e($f['name'].' · '.$f['relation'])?></option><?php endforeach;?></select></label><div class="two"><label>Patient name<input name="patient_name" value="<?=e($me['name'])?>"></label><label>Phone<input name="phone" value="<?=e((string)($me['phone']??''))?>" required></label></div><label>Email<input type="email" name="email" value="<?=e((string)($me['email']??''))?>"></label><label>Reason for visit <small>Keep it brief. Detailed medical discussion belongs in the private consultation.</small><input name="reason" maxlength="600" placeholder="e.g. follow-up, fever, skin concern"></label><label>Private note to doctor<textarea name="note" rows="3" placeholder="Optional private note"></textarea></label><label>Available slot</label><div class="do580-slots"><?php foreach($slots as $i=>$s):?><label class="do580-slot"><input type="radio" name="scheduled_at" value="<?=e($s['value'])?>" <?=$i===0?'checked':''?>><?=e($s['label'])?></label><?php endforeach;?><?php if(!$slots):?><div class="do580-alert err">No bookable slots are currently published for this consultation mode.</div><?php endif;?></div><label>Payment option<select name="payment_method"><?php if($sub):?><option value="subscription">Use subscription<?=((int)$sub['remaining_consults']>0?' · '.$sub['remaining_consults'].' credits left':'')?></option><?php endif;?><?php if(function_exists('create_payment_order')):?><option value="online_payment">Online payment</option><?php endif;?><option value="manual">Manual / pay as instructed</option></select></label><button class="do580-btn primary" <?=$slots?'':'disabled'?>>Request Appointment</button></form></section><aside><div class="do580-pricebox"><small><?=$mode==='in_person'?'Clinic visit':'Online consultation'?></small><strong><?=do580_money($mode==='in_person'?(float)$d['clinic_fee']:(float)$d['online_fee'])?></strong><p>Duration: <?=max(10,(int)$d['consultation_minutes'])?> minutes</p><?php if($sub):?><p><b>Active plan:</b> <?=e($sub['plan_name'])?></p><?php endif;?></div><div class="do580-clinical-note">Appointment booking does not provide emergency care. For severe or life-threatening symptoms, contact emergency services or the nearest emergency department.</div></aside></div></main><?php do580_public_footer(); ?>
